#include <bits/stdc++.h>
using namespace std;
using int64 = long long;
using i128 = __int128_t;

i128 mul_mod(i128 a, i128 b, i128 mod) {
    return (a * b) % mod;
}

i128 add_mod(i128 a, i128 b, i128 mod) {
    a += b;
    if (a >= mod) a -= mod;
    return a;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 n, sx, sy, dx, dy, t;
    cin >> n >> sx >> sy >> dx >> dy >> t;

    if (t == 0) {
        cout << sx << " " << sy << "\n";
        return 0;
    }

    i128 M = n;

    // State vector: [x, y, dx, dy, t, 1] all mod n
    array<array<i128, 6>, 6> A{};
    for (int i = 0; i < 6; ++i)
        for (int j = 0; j < 6; ++j)
            A[i][j] = 0;

    // x' = 2*x + y + dx + t + 2
    A[0][0] = 2; A[0][1] = 1; A[0][2] = 1; A[0][4] = 1; A[0][5] = 2;
    // y' = x + 2*y + dy + t + 2
    A[1][0] = 1; A[1][1] = 2; A[1][3] = 1; A[1][4] = 1; A[1][5] = 2;
    // dx' = 2*x + y + dx + t + 2
    A[2][0] = 2; A[2][1] = 1; A[2][2] = 1; A[2][4] = 1; A[2][5] = 2;
    // dy' = x + 2*y + dy + t + 2
    A[3][0] = 1; A[3][1] = 2; A[3][3] = 1; A[3][4] = 1; A[3][5] = 2;
    // t' = t + 1
    A[4][4] = 1; A[4][5] = 1;
    // 1' = 1
    A[5][5] = 1;

    // Initial vector
    array<i128, 6> v{};
    auto to_mod = [&](int64 x) -> i128 {
        i128 res = x % M;
        if (res < 0) res += M;
        return res;
    };
    v[0] = to_mod(sx - 1);  // 0-indexed
    v[1] = to_mod(sy - 1);
    v[2] = to_mod(dx);
    v[3] = to_mod(dy);
    v[4] = 0;
    v[5] = 1;

    // Fast exponentiation
    i128 exp = t;
    array<array<i128, 6>, 6> R{};
    for (int i = 0; i < 6; ++i)
        for (int j = 0; j < 6; ++j)
            R[i][j] = (i == j) ? 1 : 0;

    while (exp > 0) {
        if (exp & 1) {
            // R = R * A
            array<array<i128, 6>, 6> R_new{};
            for (int i = 0; i < 6; ++i)
                for (int j = 0; j < 6; ++j)
                    R_new[i][j] = 0;
            for (int i = 0; i < 6; ++i)
                for (int k = 0; k < 6; ++k)
                    if (R[i][k] != 0)
                        for (int j = 0; j < 6; ++j)
                            if (A[k][j] != 0)
                                R_new[i][j] = add_mod(R_new[i][j], mul_mod(R[i][k], A[k][j], M), M);
            R = R_new;
        }
        // A = A * A
        array<array<i128, 6>, 6> A_new{};
        for (int i = 0; i < 6; ++i)
            for (int j = 0; j < 6; ++j)
                A_new[i][j] = 0;
        for (int i = 0; i < 6; ++i)
            for (int k = 0; k < 6; ++k)
                if (A[i][k] != 0)
                    for (int j = 0; j < 6; ++j)
                        if (A[k][j] != 0)
                            A_new[i][j] = add_mod(A_new[i][j], mul_mod(A[i][k], A[k][j], M), M);
        A = A_new;
        exp >>= 1;
    }

    // Multiply R * v
    array<i128, 6> res{};
    for (int i = 0; i < 6; ++i) {
        res[i] = 0;
        for (int j = 0; j < 6; ++j)
            res[i] = add_mod(res[i], mul_mod(R[i][j], v[j], M), M);
    }

    int64 final_x = (int64)res[0] + 1;
    int64 final_y = (int64)res[1] + 1;
    cout << final_x << " " << final_y << "\n";
    return 0;
}
